package test;
import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.core.CoreException;

public class MyClass {
    public static final String MY_TEMPLATE_ID = org.eclipse.jdt.ui.CodeGeneration.CLASS_BODY_TEMPLATE_ID;

    public void generate(ICompilationUnit cu, String typeComment, String typeContent, String lineDelimiter) throws CoreException {
        String content = org.eclipse.jdt.ui.CodeGeneration.getCompilationUnitContent(cu, typeComment, typeContent, lineDelimiter);
        System.out.println(content);
    }
}

